def test_hyb_mgga_xc_b86b95_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_b86b95", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.163068688883486e+00, -3.103980783244004e+00, -3.021254976198138e+00, -2.906807870333910e+00, -2.751173370275131e+00, -2.544700025170617e+00, -2.280337889401975e+00, -1.958553541702703e+00, -1.593254751410584e+00, -1.210597993434040e+00, -8.260308708276439e-01, -5.668035990210314e-01, -4.716032917763303e-01, -3.866994027403476e-01, -2.842416324792020e-01, -1.848946888365866e-01, -1.024909425847686e-01, -3.872644812089137e-02, -8.487048183041537e-03, -9.548782466860428e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


